// Included into Rust generated by AIN when the Rust backend is selected.
// A local-only desktop UI host. No external Rust crates are required.
fn ainex_json(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c <= '\u{001f}' => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn ainex_decode(s: &str) -> String {
    let data = s.as_bytes();
    let mut bytes = Vec::with_capacity(data.len());
    let mut i = 0;
    while i < data.len() {
        if data[i] == b'+' { bytes.push(b' '); }
        else if data[i] == b'%' && i + 2 < data.len() {
            let hex = |b: u8| -> Option<u8> {
                match b { b'0'..=b'9' => Some(b - b'0'), b'a'..=b'f' => Some(b - b'a' + 10),
                    b'A'..=b'F' => Some(b - b'A' + 10), _ => None }
            };
            if let (Some(a), Some(b)) = (hex(data[i + 1]), hex(data[i + 2])) {
                bytes.push(a * 16 + b);
                i += 2;
            } else { bytes.push(data[i]); }
        } else { bytes.push(data[i]); }
        i += 1;
    }
    String::from_utf8_lossy(&bytes).to_string()
}

fn ainex_form(body: &str, key: &str) -> String {
    body.split('&').filter_map(|part| part.split_once('='))
        .find(|(name, _)| *name == key)
        .map(|(_, value)| ainex_decode(value))
        .unwrap_or_default()
}

fn ainex_reply(stream: &mut std::net::TcpStream, status: &str, mime: &str, body: &str) {
    use std::io::Write;
    let response = format!(
        "HTTP/1.1 {}\r\nContent-Type: {}; charset=utf-8\r\nContent-Length: {}\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nContent-Security-Policy: default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; form-action 'none'; frame-ancestors 'none'\r\nConnection: close\r\n\r\n",
        status, mime, body.as_bytes().len()
    );
    let _ = stream.write_all(response.as_bytes());
    let _ = stream.write_all(body.as_bytes());
}

fn ainex_http_read(stream: &mut std::net::TcpStream) -> Result<(String, String), String> {
    use std::io::Read;
    let _ = stream.set_read_timeout(Some(std::time::Duration::from_secs(12)));
    let mut buf = Vec::new();
    let mut chunk = [0_u8; 4096];
    let boundary = loop {
        if buf.len() > 150_000 { return Err("Request is too large".into()); }
        let n = stream.read(&mut chunk).map_err(|e| format!("Read failed: {e}"))?;
        if n == 0 { return Err("Connection ended early".into()); }
        buf.extend_from_slice(&chunk[..n]);
        if let Some(pos) = buf.windows(4).position(|w| w == b"\r\n\r\n") { break pos + 4; }
        if buf.len() > 16_384 { return Err("Request headers too large".into()); }
    };
    let header = std::str::from_utf8(&buf[..boundary]).map_err(|_| "Invalid headers")?.to_string();
    let length = header.lines().filter_map(|line| {
        let (name, value) = line.split_once(':')?;
        if name.eq_ignore_ascii_case("content-length") { value.trim().parse::<usize>().ok() }
        else { None }
    }).next().unwrap_or(0);
    if length > 128_000 { return Err("Request body is too large".into()); }
    while buf.len() - boundary < length {
        let n = stream.read(&mut chunk).map_err(|e| format!("Read failed: {e}"))?;
        if n == 0 { return Err("Request body ended early".into()); }
        buf.extend_from_slice(&chunk[..n]);
    }
    let body = String::from_utf8(buf[boundary..boundary + length].to_vec())
        .map_err(|_| "Request body is not UTF-8")?;
    Ok((header, body))
}

fn ainex_model(model: &str) -> Result<(), String> {
    if model.len() > 128 || !model.chars().all(|c|
        c.is_ascii_alphanumeric() || matches!(c, '.' | '/' | '-' | '_' | ':')
    ) { return Err("Invalid model name".into()); }
    Ok(())
}

fn ainex_deepinfra(system: &str, prompt: &str, model: &str) -> Result<String, String> {
    use std::io::Write;
    use std::process::{Command, Stdio};
    let token = std::env::var("DEEPINFRA_API_KEY")
        .map_err(|_| "Set DEEPINFRA_API_KEY before starting Ainex".to_string())?;
    let selected = if model.is_empty() { "deepseek-ai/DeepSeek-V4-Flash-0731" } else { model };
    ainex_model(selected)?;
    let payload = format!(
        "{{\"model\":{},\"messages\":[{{\"role\":\"system\",\"content\":{}}},{{\"role\":\"user\",\"content\":{}}}]}}",
        ainex_json(selected), ainex_json(system), ainex_json(prompt)
    );
    let mut curl = Command::new("curl")
        .args(["--silent", "--show-error", "--fail-with-body", "--max-time", "120", "--request", "POST",
            "https://api.deepinfra.com/v1/openai/chat/completions",
            "--header", "Content-Type: application/json",
            "--header", &format!("Authorization: Bearer {token}"),
            "--data-binary", "@-"])
        .stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped())
        .spawn().map_err(|e| format!("Unable to start curl: {e}"))?;
    curl.stdin.take().ok_or("Missing curl stdin")?.write_all(payload.as_bytes())
        .map_err(|e| format!("Unable to send request: {e}"))?;
    let out = curl.wait_with_output().map_err(|e| format!("curl failed: {e}"))?;
    if !out.status.success() {
        return Err(format!("DeepInfra request failed: {}", String::from_utf8_lossy(&out.stderr).trim()));
    }
    // jq handles JSON escapes, nulls, and Unicode. Avoid fragile substring parsing.
    let mut jq = Command::new("jq")
        .args(["-er", ".choices[0].message.content | select(type == \"string\")"])
        .stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped())
        .spawn().map_err(|e| format!("Unable to start jq: {e}"))?;
    jq.stdin.take().ok_or("Missing jq stdin")?.write_all(&out.stdout)
        .map_err(|e| format!("Unable to pass response to jq: {e}"))?;
    let parsed = jq.wait_with_output().map_err(|e| format!("jq failed: {e}"))?;
    if !parsed.status.success() {
        return Err(format!("Unexpected DeepInfra response: {}", String::from_utf8_lossy(&out.stdout).chars().take(600).collect::<String>()));
    }
    Ok(String::from_utf8_lossy(&parsed.stdout).trim_end().to_string())
}

fn ainex_chatgpt(prompt: &str, model: &str) -> Result<String, String> {
    use std::io::Write;
    use std::process::{Command, Stdio};
    ainex_model(model)?;
    // ChatGPT subscription sign-in stays entirely inside the official Codex CLI.
    // The app never reads ~/.codex/auth.json or handles OAuth credentials.
    let path = std::env::temp_dir().join(format!(
        "ainex-{}-{}.txt", std::process::id(),
        std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH)
            .map_err(|e| e.to_string())?.as_nanos()
    ));
    let mut cmd = Command::new("codex");
    cmd.args(["exec", "--skip-git-repo-check", "--sandbox", "read-only",
        "--output-last-message"]).arg(&path);
    if !model.is_empty() { cmd.args(["--model", model]); }
    cmd.arg("-").stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped());
    let mut child = cmd.spawn().map_err(|e|
        format!("Cannot run codex: {e}. Install Codex and run 'codex login' first."))?;
    child.stdin.take().ok_or("Missing Codex stdin")?.write_all(prompt.as_bytes())
        .map_err(|e| format!("Cannot send prompt to Codex: {e}"))?;
    let result = child.wait_with_output().map_err(|e| format!("Codex failed: {e}"))?;
    let answer = std::fs::read_to_string(&path);
    let _ = std::fs::remove_file(path);
    if !result.status.success() {
        return Err(format!("Codex failed. Run 'codex login' if necessary. {}",
            String::from_utf8_lossy(&result.stderr).chars().take(600).collect::<String>()));
    }
    answer.map_err(|e| format!("Codex returned no answer: {e}"))
}

fn ainex_connection(
    mut stream: std::net::TcpStream,
    html: std::sync::Arc<String>,
    system: std::sync::Arc<String>,
    origin: std::sync::Arc<String>,
) {
    let (header, body) = match ainex_http_read(&mut stream) {
        Ok(v) => v,
        Err(message) => {
            ainex_reply(&mut stream, "400 Bad Request", "application/json",
                &format!("{{\"error\":{}}}", ainex_json(&message)));
            return;
        }
    };
    let first = header.lines().next().unwrap_or("");
    if first == "GET / HTTP/1.1" || first == "GET /index.html HTTP/1.1" {
        ainex_reply(&mut stream, "200 OK", "text/html", &html);
    } else if first == "POST /chat HTTP/1.1" {
        // Custom header requires a CORS preflight from another origin; no CORS
        // response is provided. Also enforce the exact localhost Origin.
        let headers = header.to_ascii_lowercase();
        let expected = format!("origin: {}", origin.to_ascii_lowercase());
        if !headers.lines().any(|s| s.trim() == "x-ainex-client: 1")
            || !headers.lines().any(|s| s.trim() == expected) {
            ainex_reply(&mut stream, "403 Forbidden", "application/json", "{\"error\":\"Invalid request origin\"}");
            return;
        }
        let provider = ainex_form(&body, "provider");
        let model = ainex_form(&body, "model");
        let prompt = ainex_form(&body, "prompt");
        if prompt.trim().is_empty() {
            ainex_reply(&mut stream, "400 Bad Request", "application/json", "{\"error\":\"Message is empty\"}");
            return;
        }
        let result = match provider.as_str() {
            "deepinfra" => ainex_deepinfra(&system, &prompt, &model),
            "chatgpt" => ainex_chatgpt(&format!("{}\n\nUser request:\n{}", system, prompt), &model),
            _ => Err("Unknown provider".to_string()),
        };
        match result {
            Ok(reply) => ainex_reply(&mut stream, "200 OK", "application/json",
                &format!("{{\"reply\":{}}}", ainex_json(&reply))),
            Err(error) => ainex_reply(&mut stream, "502 Bad Gateway", "application/json",
                &format!("{{\"error\":{}}}", ainex_json(&error))),
        }
    } else {
        ainex_reply(&mut stream, "404 Not Found", "text/plain", "Not found");
    }
}

fn ain_desktop(title: String, system: String, page: String) {
    let html = std::fs::read_to_string(&page)
        .unwrap_or_else(|e| panic!("Cannot read desktop UI file '{}': {}", page, e));
    let listener = std::net::TcpListener::bind(("127.0.0.1", 0))
        .expect("Cannot bind local Ainex desktop server");
    let address = listener.local_addr().expect("Cannot discover local port");
    let url = format!("http://127.0.0.1:{}/", address.port());
    eprintln!("{} listening at {}", title, url);
    let _ = std::process::Command::new("xdg-open").arg(&url)
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null()).spawn();
    let html = std::sync::Arc::new(html);
    let system = std::sync::Arc::new(system);
    let origin = std::sync::Arc::new(format!("http://127.0.0.1:{}", address.port()));
    for connection in listener.incoming() {
        match connection {
            Ok(stream) => {
                let html = html.clone();
                let system = system.clone();
                let origin = origin.clone();
                std::thread::spawn(move || ainex_connection(stream, html, system, origin));
            }
            Err(e) => eprintln!("Ainex connection error: {}", e),
        }
    }
}
